// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Soft".

When I read the challenge topic, I immediately thought of my
favorite socks that I was wearing at that moment. They're soft
and cozy, in blue and white, and my grandmother knitted them for
me. They're so warm this time of year! I wanted to play up the
softness and make the shader more interesting with the movement.
*/

OPC.slider('zoom', 1, -20, 60, 1);
OPC.slider('acceleration', 1.0, 0.0, 6.0, 0.1);
let theShader, dpr = Math.max(1, window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'


function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2553155/files/vert.glsl', 'frag.glsl');
}

function setup() {
	OPC.collapse();
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function draw() {
  shader(theShader);
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
  theShader.setUniform("zoom", zoom);
  theShader.setUniform("acceleration", acceleration);
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; 
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;
uniform float zoom;
uniform float acceleration;
#define FC gl_FragCoord.xy
#define R resolution
#define MN min(R.x,R.y)
#define T (10.+time*.5*acceleration)
#define S smoothstep
#define SE(v,s) S(s+1./MN,s-1./MN,v)
#define gold vec3(1,.9,.6)
#define bron vec3(.3,.2,.05)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define lum(a) dot(a,vec3(.21,.71,.07))
// Returns a pseudo random number for a given number (white noise)
float rnd(float a) {
	vec2 p=fract(a*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (value noise)
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p),u=f*f*(3.-2.*f), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Returns a pseudo random number for a given point (fractal noise)
float fbm(vec2 p) {
	float t=.0, a=1., h=.0; mat2 m=mat2(1.6,-.6,.6,1.6);
	for (float i=.0; i<5.; i++) {
		t+=a*noise(p);
		p*=m*2.;
		a*=.5;
		h+=a;
	}
	return t/h;
}
// NuSan's famous curve function "to make movements more interesting".
// https://youtu.be/mNkEIrySZGI?si=X45Zvk1HmHqjWCVG&t=2324
// Returns a value interpolated between two random values at a given point t with an exponent e
float curve(float t, float e) {
	t/=e;
	return mix(
		rnd(floor(t)),
		rnd(floor(t)+1.),
		pow(S(.0,1.,fract(t)),10.)
	);
}
void main(void) {
	vec2 uv=(FC-.5*R)/MN, st=uv;
	// store the y componten of the unit vector
	float y=uv.y;
	// move away from the center (reveals more irregular patterns)
	uv+=vec2(5,4);
	// animate the fabric horizontally
	uv.x*=1.+.0025*sin(uv.y*.25+y*1.5+T*4.5)-dot(st,uv)*.01;
	// animate the fabric vertically
	uv.y*=1.+.005*sin(T*4.5);
	// create animation for horizontal folds
	float z=uv.y-(1.-sin(sin(T*(1.+curve(T*.5,4.2)*.02)+6.3*uv.x)))*.5;
	// add "more interesting movement" to the vertical animation
	uv.y+=1.-pow(cos(.75*sin(T+curve(T*.5,8.)+2.*(1.+curve(T*2.5,14.4))*(uv*rot(.125)).x)),2.)*.05;
	// add animation for horizontal folds
	uv.x+=z*.05;
	// zoom out
	uv*=24.+zoom;
	// create grid for knitting pattern
	vec2 p=fract(uv*4.)-.5;
	// initialize color vector
	vec3 col=vec3(0);
	// track distance to color pattern
	float d=5e5;
	// define constants for pattern size and rotation angle
	const float e=.25, a=1.575;
	// deform the unit vector to create the color pattern
	for (float i=.0; i<3.; i++) {
		// calculate the distance to the grid
		d=min(d,max(abs(p.x)-e,abs(p.y)-e));
		// fold the x component
		uv.x=abs(uv.x)-.5;
		// distort the y component
		uv.y+=sin(uv.x*22.)*.1;
		// adjust the angle of the color pattern
		uv*=rot(a);
	}
	// slow down time 
	float t=T*.1;
	// add additional animation in vertical direction
	uv.y+=sin(t*.1)*.5;
	// randomly add the wave (slightly animated)
	col+=fbm(t*.1-uv+noise(t*.7+uv*4.));
	// colorize the pattern
	col*=mix(gold,bron,d);
	// invert the colors (1-gold results in blues)
	col=1.-col;
	// calculate the vignette
	vec2 vp=(FC/R)*2.-1.;
	vp*=vp*vp*vp*vp;
	vp*=.7;
	float v=pow(dot(vp,vp),2.);
	// add the vignette (in blue) to the corners
	col=mix(col,1.-gold,clamp(v,.0,1.));
	// output the pixel's color to the screen
	O=vec4(col,1);
}

